{
  "packet_id": "H6-T04-2",
  "claim_id": "C017",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C017.main",
    "value": "Before release, evaluation should specify eligible accounts, the first-publication outcome, recording checks and a common observation window covering intended roster opportunity.",
    "scope": "Prospective evaluation design; the window's duration and how it accommodates differing intended dates are unspecified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P009 supplies all four design requirements without specifying their implementation."
    }
  },
  "signal_basis": {
    "component_id": "C017.signal_basis",
    "value": "The proposed evaluation observes changes in the proportion reaching traceable first publication within a predefined window. Interpretation requires accounting for publication opportunities that have not occurred and checking whether recording changes create apparent improvement.",
    "scope": "Prospective measurement of first publication; observations are proposed, and intended roster dates can change.",
    "provenance": {
      "refs": [
        {
          "source_id": "P015",
          "role": "SUPPORT"
        },
        {
          "source_id": "P016",
          "role": "SUPPORT"
        },
        {
          "source_id": "P024",
          "role": "SUPPORT"
        },
        {
          "source_id": "P025",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the intended measurement and its prospective, timing and recording qualifications."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C017.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The procedural claim is supported without requiring an unresolved empirical relation."
    }
  },
  "rationale": "Measuring a publication proportion requires defined eligibility, an outcome and an observation window. The stated timing and recording limitations also warrant specifying publication opportunity and recording checks before release. This licenses the prospective design requirement within its stated bounds.",
  "uncertainty": "The mapping leaves window duration and accommodation of differing or changing roster dates unresolved. That limits implementation specificity without defeating the requirement to specify them.",
  "anomalies": []
}
